import java.util.*;
/** Binary min heap plus simplified advanced heap variant notes. */
class TeachingMinHeap { ArrayList<Integer> a=new ArrayList<Integer>(); int parent(int i){return(i-1)/2;} int left(int i){return 2*i+1;} void insert(int x){a.add(x);for(int i=a.size()-1;i>0&&a.get(i)<a.get(parent(i));i=parent(i))swap(i,parent(i));} int findMin(){return a.get(0);} int deleteMin(){int m=a.get(0);a.set(0,a.remove(a.size()-1));down(0);return m;} void down(int i){while(left(i)<a.size()){int c=left(i),r=c+1;if(r<a.size()&&a.get(r)<a.get(c))c=r;if(a.get(i)<=a.get(c))break;swap(i,c);i=c;}} void decreaseKey(int i,int v){a.set(i,v);while(i>0&&a.get(i)<a.get(parent(i))){swap(i,parent(i));i=parent(i);}} void increaseKey(int i,int v){a.set(i,v);down(i);} void deleteAt(int i){decreaseKey(i,Integer.MIN_VALUE);deleteMin();} void swap(int i,int j){int t=a.get(i);a.set(i,a.get(j));a.set(j,t);} static void advancedVariants(){System.out.println("d-heap: more children reduce height; leftist heap: null path length; skew heap: self-adjusting merge; binomial queue: forest of binomial trees.");} }
